package io.forgeloop.runner;import java.util.*;public record LocalMcpConfiguration(String name,String command,List<String> arguments,String contextTool,String toolArguments,int revision){public LocalMcpConfiguration{arguments=List.copyOf(arguments);if(name==null||name.isBlank()||command==null||command.isBlank()||contextTool==null||contextTool.isBlank())throw new IllegalArgumentException("MCP configuration is incomplete");}}
